<?php
require_once dirname(__DIR__,2).'/includes/bootstrap.php';
require_once ROOT_PATH.'/includes/cost_analysis.php';
require_once ROOT_PATH.'/includes/vehicle_costs.php';
require_once ROOT_PATH.'/includes/vehicle_photo.php';
require_login();require_permission('costs.view');
$preview=($_GET['source']??'preview')==='preview';
$data=$preview?vc_preview():vc_live(db());
$today=date('Y-m-d');$latest=$today;
if($preview){$dates=array_column(array_filter($data['deliveries'],fn($r)=>$r['date']<=$today),'date');if($dates)$latest=max($dates);}
$range=cost_date_range($_GET,substr($latest,0,7).'-01',min((new DateTimeImmutable($latest))->format('Y-m-t'),$today));
$mode=($_GET['comparison']??'monthly')==='yearly'?'yearly':'monthly';
$search=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$status=(string)($_GET['status']??'');
$types=array_unique(array_column($data['vehicles'],'type'));sort($types);$statuses=array_unique(array_column($data['vehicles'],'status'));sort($statuses);
$vehicles=array_values(array_filter($data['vehicles'],fn($v)=>($type===''||$v['type']===$type)&&($status===''||$v['status']===$status)&&($search===''||stripos($v['plate_number'].' '.$v['brand'].' '.$v['model'].' '.$v['type'],$search)!==false)));
$totals=[];foreach($vehicles as $v)$totals[$v['id']]=vc_period($data['deliveries'],$v['id'],$range['from'],$range['to']);
$selected=(string)($_GET['vehicle']??'');if(!in_array($selected,array_column($vehicles,'id'),true))$selected=$vehicles[0]['id']??'';
$vehicle=null;foreach($vehicles as $v)if($v['id']===$selected)$vehicle=$v;
$view=in_array(($_GET['view']??'3'),['3','6','12','selected'],true)?($_GET['view']??'3'):'3';
$analyticsTo=min($range['to'],$today);
$analyticsFrom=$view==='selected'?$range['from']:(new DateTimeImmutable($mode==='yearly'?substr($analyticsTo,0,4).'-01-01':substr($analyticsTo,0,7).'-01'))->modify('-'.((int)$view-1).' '.($mode==='yearly'?'years':'months'))->format('Y-m-d');
if($range['from']>$today){$analyticsFrom=$range['from'];$analyticsTo=$range['to'];}
if($vehicle&&!empty($vehicle['acquired'])&&$vehicle['acquired']<=$analyticsTo)$analyticsFrom=max($analyticsFrom,substr($vehicle['acquired'],0,10));
$series=$vehicle?vc_series($data['deliveries'],$selected,$analyticsFrom,$analyticsTo,$mode):[];
$analytics=$vehicle?vc_period($data['deliveries'],$selected,$analyticsFrom,$analyticsTo):null;
$last=$series?end($series):null;$before=count($series)>1?$series[count($series)-2]:null;
$comparable=vc_comparable($last,$before,$mode);
$cash=static fn($v)=>$v===null?'Not recorded':money($v/100);
$numeric=static fn($v)=>$v===null?'Not available':number_format($v,2);
$pct=static fn($v)=>$v===null?'Not available':number_format($v,1).'%';
$changeText=static fn($v)=>$v===null?'Insufficient Historical Data':sprintf('%+.1f%% vs preceding period',$v);
$goodClass=static fn($v)=>$v===null?'':($v<0?'vc-negative':'vc-positive');
$metrics=['distance'=>['Total Distance Traveled (km)','number',null], 'cost'=>['Total Operating Cost','money',null], 'cost_km'=>['Cost per Kilometer','money',false], 'fuel_km'=>['Fuel Cost per Kilometer','money',false], 'average'=>['Cost per Completed Delivery','money',false], 'maintenance'=>['Maintenance Cost','money',null], 'toll_other_average'=>['Toll & Other Cost per Delivery','money',false], 'km_l'=>['Average Fuel Consumption (km/L)','number',true]];
$photo=$vehicle&&!$preview?vehicle_photo_present($selected,vehicle_photo_records(db(),[$selected])[$selected]??[]):null;
$active_page='cost-by-vehicle';$body_class='cost-analysis-module cost-by-vehicle-page';$page_title='Cost by Vehicle';$include_chart=true;
require ROOT_PATH.'/includes/header.php';
?>
<link rel="stylesheet" href="<?=BASE_URL?>/css/cost-by-vehicle.css?v=<?=filemtime(ROOT_PATH.'/css/cost-by-vehicle.css')?>">
<div class="vc-heading cost-page-heading"><div><div class="vc-eyebrow">COST ANALYSIS (TCAO)</div><h1>Cost by Vehicle</h1><p>Analyze operating costs, trip allowances and cost efficiency per cargo vehicle.</p></div>
<form method="get" id="vc-filter" class="vc-filters"><label>Data source<select name="source"><option value="preview" <?=$preview?'selected':''?>>Test data preview</option><option value="live" <?=$preview?'':'selected'?>>Live records</option></select></label><label>Comparison Type<select name="comparison"><option value="monthly" <?=$mode==='monthly'?'selected':''?>>Monthly</option><option value="yearly" <?=$mode==='yearly'?'selected':''?>>Yearly</option></select></label><label>From<input type="date" name="from" value="<?=e($range['from'])?>" required></label><label>To<input type="date" name="to" value="<?=e($range['to'])?>" required></label><label>Vehicle Type<select name="type"><option value="">All Types</option><?php foreach($types as $option):?><option <?=$option===$type?'selected':''?>><?=e($option)?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">All Status</option><?php foreach($statuses as $option):?><option <?=$option===$status?'selected':''?>><?=e($option)?></option><?php endforeach;?></select></label><button class="tc-btn tc-btn-primary" type="submit">Apply</button></form></div>
<div class="vc-source" role="status"><?= $preview?'TEST DATA PREVIEW — 90 isolated delivery-cost records, 2025–2026. Sample vehicles and financial records never enter operational tables.':'LIVE RECORDS — Cargo fleet and completed deliveries only. Verified fuel and recorded tolls are included. Maintenance estimates are excluded; verified maintenance invoices and other expense sources are not currently available.' ?></div>
<section class="tc-card vc-section"><div class="vc-section-heading"><div><h2>Vehicle Cost Analysis</h2><p>Operating cost, trip allowances and cost efficiency per vehicle · <?=e($range['from'].' – '.$range['to'])?> (<?=ucfirst($mode)?>)</p></div><input class="vc-search" type="search" name="q" form="vc-filter" value="<?=e($search)?>" placeholder="Search vehicle (plate, model, or type)…" aria-label="Search cargo vehicles"></div><div class="vc-scroll"><table class="tc-table vc-analysis"><thead><tr><?php foreach(['Vehicle','Vehicle Type','Status','Completed Deliveries','Fuel Cost','Maintenance Cost','Toll Cost','Other Verified Costs','Total Operating Cost','Approved Trip Allowance','Remaining / Shortfall','Allowance Utilization (%)','Avg Cost / Delivery'] as $column):?><th><?=e($column)?></th><?php endforeach;?></tr></thead><tbody>
<?php if(!$vehicles):?><tr><td colspan="13">No cargo vehicles match the selected filters.</td></tr><?php endif;?>
<?php foreach($vehicles as $v):$t=$totals[$v['id']];?><tr><td><strong><?=e($v['plate_number'])?></strong><small><?=e($v['brand'].' '.$v['model'])?></small></td><td><span class="vc-type"><?=e($v['type'])?></span><small><?=isset($v['payload_capacity_kg'])?number_format((float)$v['payload_capacity_kg']).' kg payload':'Payload not recorded'?></small></td><td><span class="vc-badge <?=$v['status']==='Under Maintenance'?'vc-attention':'vc-neutral'?>"><?=e($v['status'])?></span></td><td><?=$t['count']?></td><?php foreach(['fuel','maintenance','toll','other','cost','allowance','allowance_balance','utilization','average'] as $key):?><td class="<?=$key==='allowance_balance'?$goodClass($t[$key]):''?> <?=$key==='cost'?'vc-total':''?>"><?=$key==='utilization'?($t[$key]===null?'Comparison unavailable':$pct($t[$key])):($key==='allowance'&&$t[$key]===null?'Not funded':($key==='allowance_balance'&&$t[$key]===null?($t['allowance']===null?'Comparison unavailable':'Insufficient Data'):$cash($t[$key])))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section>
<section class="tc-card vc-section"><div class="vc-section-heading"><div><h2>Vehicle Performance Analytics</h2><p>Selected-vehicle history · <?=e($analyticsFrom.' – '.$analyticsTo)?>. View period ends at the selected To date; future records are excluded.</p></div><div class="vc-selection"><label>Select Vehicle<select name="vehicle" form="vc-filter"><?php foreach($vehicles as $v):?><option value="<?=e($v['id'])?>" <?=$selected===$v['id']?'selected':''?>><?=e($v['plate_number'].' · '.$v['brand'].' '.$v['model'])?></option><?php endforeach;?></select></label><label>View Period<select name="view" form="vc-filter"><?php foreach(['3','6','12','selected'] as $option):if($mode==='yearly'&&$option==='12')continue;?><option value="<?=$option?>" <?=$view===$option?'selected':''?>><?=$option==='selected'?'Selected dates':'Last '.$option.' '.($mode==='yearly'?'Years':'Months')?></option><?php endforeach;?></select></label></div></div>
<?php if(!$vehicle):?><div class="vc-empty">No vehicle selected.</div><?php else:?>
<div class="vc-performance"><aside class="vc-profile"><div class="vc-identity"><?php if($photo&&$photo['source']==='actual'):?><img src="<?=e($photo['src'])?>" alt="<?=e($vehicle['plate_number'])?>" class="vc-photo"><?php else:?><div class="vc-truck" aria-label="Cargo vehicle illustration"><i class="bi bi-truck" aria-hidden="true"></i></div><?php endif;?><div><h3><?=e($vehicle['plate_number'])?></h3><p><?=e($vehicle['brand'].' '.$vehicle['model'])?></p><span class="vc-type"><?=e($vehicle['type'])?></span></div></div><dl><?php foreach(['model'=>'Model','type'=>'Vehicle Type','body_type'=>'Body Type','fuel_type'=>'Fuel Type','acquired'=>'Acquired Date'] as $key=>$label):?><div><dt><?=$label?></dt><dd><?=e($vehicle[$key]??'Not recorded')?></dd></div><?php endforeach;?><div><dt>Payload Capacity</dt><dd><?=isset($vehicle['payload_capacity_kg'])?number_format((float)$vehicle['payload_capacity_kg']).' kg':'Not recorded'?></dd></div><div><dt>Status</dt><dd><?=e($vehicle['status'])?></dd></div></dl></aside>
<div class="vc-analytics"><div class="vc-kpis"><?php foreach(['count'=>['Completed Deliveries','bi-box-seam'],'cost'=>['Total Operating Cost','bi-stack'],'allowance'=>['Approved Trip Allowance','bi-wallet2'],'allowance_balance'=>['Remaining / Shortfall','bi-arrow-left-right'],'utilization'=>['Allowance Utilization','bi-percent']] as $key=>[$label,$icon]):$value=$last&&$last['count']?$last[$key]:null;$delta=vc_change($value,$comparable?$before[$key]:null);?><div class="vc-kpi"><span class="vc-kpi-icon"><i class="bi <?=$icon?>" aria-hidden="true"></i></span><div><strong><?=$key==='count'?($value??'—'):($key==='utilization'?($value===null?'Unavailable':$pct($value)):($value===null&&$key==='allowance'?'Not funded':($value===null&&$key==='allowance_balance'?'Unavailable':$cash($value))))?></strong><small><?=$label?></small><span class="vc-delta"><?=e($changeText($delta))?></span></div></div><?php endforeach;?></div>
<div class="vc-chart-grid"><?php foreach(['trend'=>'Operating Cost Trend','revenue'=>'Approved Allowance vs Actual Cost','profit'=>'Transportation Cost Efficiency','average'=>'Cost per Delivery'] as $id=>$title):?><article class="vc-chart"><h3><?=$title?></h3><div class="vc-plot"><?php if(!$analytics['count']):?><div class="vc-empty">No data available</div><?php else:?><canvas id="vc-<?=$id?>" role="img" aria-label="<?=e($title.' for '.$vehicle['plate_number'])?>"></canvas><?php endif;?></div></article><?php endforeach;?></div></div></div>
<?php if(!$comparable):?><div class="vc-history-note">Insufficient Historical Data — matching date coverage or completed-delivery evidence is unavailable for the last two <?=e($mode==='yearly'?'years':'months')?>.</div><?php endif;?>
<?php endif;?></section>
<section class="tc-card vc-section"><div class="vc-section-heading"><div><h2>Vehicle Cost Efficiency Analysis</h2><p>Selected-vehicle values use recorded distance and verified costs. Cost statuses compare cost per completed delivery; distance changes describe activity, not efficiency. Missing evidence is not rated.</p></div></div><div class="vc-scroll"><table class="tc-table vc-efficiency"><thead><tr><th>Metric</th><?php foreach($series as $s):?><th><?=e($s['label'])?></th><?php endforeach;?><th>Change (last two periods)</th><th>Status</th></tr></thead><tbody><?php foreach($metrics as $key=>[$label,$format,$higher]):$currentValue=$last&&$last['count']?$last[$key]:null;$previousValue=$comparable?$before[$key]:null;$delta=vc_change($currentValue,$previousValue);$state=$higher===null?'Insufficient Data':vc_status($currentValue,$previousValue,$higher);if($higher===null&&$delta!==null){if($key==='distance')$state=abs($delta)<5?'Stable':'Activity Changed';else $state=vc_status($currentValue/$last['count'],$previousValue/$before['count']);}?><tr><td><?=$label?></td><?php foreach($series as $s):$value=$s['count']?$s[$key]:null;?><td><?=$format==='money'?$cash($value):$numeric($value)?></td><?php endforeach;?><td><?=$delta===null?'Not available':sprintf('%+.1f%%',$delta)?></td><td><span class="vc-badge <?=$state==='Improving'?'vc-positive-bg':($state==='Needs Attention'?'vc-attention':'vc-neutral')?>"><?=e($state)?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="tc-card vc-section"><div class="vc-section-heading"><div><h2>Funding &amp; Recorded Costs by Vehicle</h2><p>Remaining / Shortfall = approved allowance − actual recorded cost. Unused allowance is not evidence of returned funds. Partial funding coverage has no aggregate balance.</p></div></div><div class="vc-scroll"><table class="tc-table vc-funding"><thead><tr><?php foreach(['Vehicle','Vehicle Type','Completed Deliveries','Estimated Cost','Approved Trip Allowance','Actual Recorded Cost','Remaining / Shortfall','Status'] as $label):?><th><?=$label?></th><?php endforeach;?></tr></thead><tbody><?php if(!$vehicles):?><tr><td colspan="8">No cargo vehicles match the selected filters.</td></tr><?php endif;?><?php foreach($vehicles as $v):$t=$totals[$v['id']];$fundState=$t['remaining']===null?'Insufficient Data':($t['remaining']<0?'Over Allowance':'Under Allowance');?><tr><td><strong><?=e($v['plate_number'])?></strong><small><?=e($v['brand'].' '.$v['model'])?></small></td><td><?=e($v['type'])?></td><td><?=$t['count']?></td><td><?=$cash($t['estimate'])?><?php if($t['count']&&!$t['estimate_complete']):?><small>Partial estimate coverage</small><?php endif;?></td><td><?=$cash($t['funding'])?><?php if($t['unfunded_count']):?><small><?=$t['funded_count']?> of <?=$t['count']?> deliveries funded</small><?php endif;?></td><td><?=$cash($t['cost'])?></td><td class="<?=$goodClass($t['remaining'])?>"><?=$t['remaining']===null?'Comparison unavailable':$cash($t['remaining'])?></td><td><span class="vc-badge <?=$t['remaining']===null?'vc-neutral':($t['remaining']<0?'vc-attention':'vc-positive-bg')?>"><?=$fundState?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<?php
